const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "//////////////////////////////////////////////////////\n// GENERATOR\n//////////////////////////////////////////////////////\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n//////////////////////////////////////////////////////\n// ENUMS\n//////////////////////////////////////////////////////\n\nenum Role {\n  USER\n  ADMIN\n  BRANCH_ADMIN\n  SUPER_ADMIN\n  PROFESSIONAL\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum AuthProvider {\n  PHONE_OTP\n  EMAIL_OTP\n  GOOGLE\n  APPLE\n  GUEST\n}\n\nenum AuthIdentifierType {\n  PHONE\n  EMAIL\n  // Apple's stable per-user, per-app identifier (\"sub\" claim). Apple only\n  // returns email/name on the user's first-ever authorization, so this is\n  // the only value guaranteed to be present on every subsequent Apple\n  // sign-in and is used as the durable lookup key for that provider.\n  APPLE_SUB\n}\n\nenum AccountDeletionStatus {\n  NONE\n  REQUESTED\n  CANCELLED\n  COMPLETED\n}\n\nenum AccountDeletionReason {\n  NO_LONGER_NEED_APP\n  USING_ANOTHER_SERVICE\n  BAD_EXPERIENCE\n  TOO_MANY_NOTIFICATIONS\n  PRIVACY_CONCERNS\n  DIFFICULT_TO_USE\n  SERVICE_NOT_AVAILABLE\n  OTHER\n}\n\nenum OTPType {\n  LOGIN\n  REGISTER\n  CHECKOUT\n  PHONE_UPDATE\n  ACCOUNT_RECOVERY\n  ACCOUNT_DELETE\n  ADMIN_INVITE\n}\n\nenum AddressLabel {\n  HOME\n  WORK\n  OTHER\n}\n\nenum Weekday {\n  SUNDAY\n  MONDAY\n  TUESDAY\n  WEDNESDAY\n  THURSDAY\n  FRIDAY\n  SATURDAY\n}\n\nenum ServicePriceType {\n  FIXED\n  STARTING_AT\n  INSPECTION\n  TIME_BASED\n  AREA_BASED\n  DISTANCE_BASED\n  PACKAGE_BASED\n  QUANTITY_BASED\n  VARIANT_BASED\n  CUSTOM_QUOTE\n}\n\nenum ServicePricingType {\n  FIXED\n  VARIABLE\n  CONSULTATION\n}\n\nenum ServiceDurationType {\n  FIXED\n  FLEXIBLE\n}\n\nenum PricingRuleType {\n  PER_HOUR\n  PER_UNIT\n  PER_PERSON\n  PER_SQFT\n}\n\nenum ServiceType {\n  CATEGORY\n  GROUP\n  SERVICE\n}\n\nenum ServiceBookingMode {\n  MULTI\n  SINGLE\n}\n\n//////////////////////////////////////////////////////\n// BOOKING STATUS & PAYMENT STATUS\n//////////////////////////////////////////////////////\n\nenum BookingStatus {\n  CREATED\n  PENDING\n  BOOKED\n  CONFIRMED\n  TECHNICIAN_ASSIGNED\n  TECHNICIAN_EN_ROUTE\n  TECHNICIAN_ARRIVED\n  VISIT_SCHEDULED\n  INSPECTION_COMPLETED\n  QUOTE_SENT\n  QUOTE_APPROVED\n  QUOTE_REJECTED\n  IN_PROGRESS\n  WORK_IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  NOT_REQUIRED\n  FAILED\n  REFUNDED\n}\n\nenum PaymentGateway {\n  PHONEPE\n  PAYU\n}\n\nenum CouponDiscountType {\n  PERCENT\n  FLAT\n}\n\nenum OfferDiscountType {\n  PERCENT\n  FLAT\n}\n\nenum NotificationType {\n  BOOKING_CREATED\n  BOOKING_STATUS_UPDATED\n  PAYMENT_STATUS_UPDATED\n  BOOKING_CANCELLED\n  PROMOTIONAL_OFFER\n  COUPON\n  ANNOUNCEMENT\n  TRANSACTIONAL_UPDATE\n  PROFESSIONAL_APPROVED\n  PROFESSIONAL_REJECTED\n  PROFESSIONAL_SUSPENDED\n  PROFESSIONAL_REACTIVATED\n  JOB_OFFER_RECEIVED\n  DISPATCH_NO_PROFESSIONALS\n}\n\nenum NotificationDeliveryChannel {\n  PUSH\n  EMAIL\n  SMS\n  WHATSAPP\n}\n\nenum NotificationDeliveryStatus {\n  SENT\n  FAILED\n  SKIPPED\n}\n\nenum NotificationEvent {\n  USER_SIGNUP_WELCOME\n  BOOKING_CONFIRMATION\n  BOOKING_COMPLETION\n  PAYMENT_CONFIRMATION\n  NOTIFICATION_CAMPAIGN\n}\n\nenum NotificationCampaignStatus {\n  DRAFT\n  SCHEDULED\n  PROCESSING\n  SENT\n  PARTIAL\n  FAILED\n  CANCELLED\n}\n\nenum NotificationAudienceType {\n  ALL_USERS\n  SEGMENT\n  INDIVIDUAL_USERS\n}\n\nenum NotificationAudienceSegment {\n  ACTIVE_LAST_30_DAYS\n  INACTIVE_LAST_30_DAYS\n  USERS_WITHOUT_BOOKINGS\n  USERS_WITH_BOOKINGS\n  RECENT_SIGNUPS\n}\n\nenum NotificationDeliveryState {\n  PENDING\n  DELIVERED\n  FAILED\n  SKIPPED\n}\n\n//////////////////////////////////////////////////////\n// PROFESSIONAL DOMAIN ENUMS\n//////////////////////////////////////////////////////\n\n// Admin-controlled onboarding/compliance state. Kept independent of\n// ProfessionalAvailabilityStatus: a professional can be APPROVED but OFFLINE,\n// or (if suspended) forced OFFLINE regardless of their own toggle.\nenum ProfessionalVerificationStatus {\n  PENDING\n  UNDER_REVIEW\n  APPROVED\n  REJECTED\n  SUSPENDED\n  BLOCKED\n}\n\n// Professional-controlled (or app-driven) real-time state. Never combined\n// with verification status.\nenum ProfessionalAvailabilityStatus {\n  OFFLINE\n  ONLINE\n  BUSY\n}\n\nenum ProfessionalDocumentType {\n  ID_PROOF\n  ADDRESS_PROOF\n  CERTIFICATION\n  POLICE_VERIFICATION\n  PROFILE_PHOTO\n  OTHER\n}\n\nenum ProfessionalDocumentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum BookingProfessionalOfferStatus {\n  PENDING\n  SENT\n  VIEWED\n  ACCEPTED\n  REJECTED\n  EXPIRED\n  CANCELLED\n}\n\n// Snapshot ledger status. The commission/fee applied is stored as an actual\n// amount on ProfessionalEarning at creation time, never as a rate here.\nenum ProfessionalEarningStatus {\n  PENDING\n  ACCRUED\n  PAYABLE\n  PAID\n  REVERSED\n  CANCELLED\n}\n\nenum PayoutStatus {\n  PENDING\n  PROCESSING\n  PAID\n  FAILED\n  CANCELLED\n}\n\n// Tracks the dispatch/matching engine's progress for a booking, separate\n// from BookingStatus (customer-facing) and ProfessionalVerificationStatus\n// (professional-facing). ASSIGNED is not set by anything in this phase —\n// it's pre-modeled for the acceptance/assignment phase that follows.\nenum DispatchStatus {\n  NOT_DISPATCHED\n  IN_PROGRESS\n  OFFERS_SENT\n  NO_ELIGIBLE_PROFESSIONALS\n  EXPIRED_UNFILLED\n  ASSIGNED\n  CANCELLED\n}\n\n//////////////////////////////////////////////////////\n// USER (ACCOUNT ONLY)\n//////////////////////////////////////////////////////\n\nmodel User {\n  id String @id @default(cuid())\n\n  role Role @default(USER)\n\n  isActive         Boolean   @default(true)\n  isBlocked        Boolean   @default(false)\n  deletedAt        DateTime?\n  scheduledPurgeAt DateTime?\n\n  deletionRequestedAt      DateTime?\n  deletionScheduledFor     DateTime?\n  deletionCancelledAt      DateTime?\n  deletionCompletedAt      DateTime?\n  deletionStatus           AccountDeletionStatus  @default(NONE)\n  deletionReason           AccountDeletionReason?\n  deletionFeedback         String?\n  deletionRequestIp        String?\n  deletionRequestedDevice  String?\n  cancelledByLogin         Boolean                @default(false)\n  finalDeletionJobStatus   String?\n  finalDeletionJobMetadata Json?\n  finalDeletionAttemptedAt DateTime?\n\n  totalBookings Int       @default(0)\n  lastActiveAt  DateTime?\n\n  profile UserProfile?\n\n  authMethods UserAuth[]\n\n  addresses Address[]\n\n  adminBranches BranchAdmin[]\n\n  identities CustomerIdentity[]\n\n  emailVerificationToken EmailVerificationToken?\n\n  bookings        Booking[]\n  bookingTimeline BookingTimeline[]\n  serviceReviews  ServiceReview[]\n\n  professionalProfile         ProfessionalProfile?\n  professionalVerifications   ProfessionalProfile[]  @relation(\"ProfessionalVerifiedBy\")\n  professionalDocumentReviews ProfessionalDocument[] @relation(\"ProfessionalDocumentReviewedBy\")\n\n  notifications            Notification[]\n  notificationCampaigns    NotificationCampaign[]    @relation(\"NotificationCampaignCreatedBy\")\n  notificationDeliveryLogs NotificationDeliveryLog[]\n  deviceTokens             DeviceToken[]\n\n  carts Cart[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([deletedAt])\n  @@index([scheduledPurgeAt])\n  @@index([deletionStatus, deletionScheduledFor])\n  @@index([deletionReason])\n  @@index([deletionRequestedAt])\n}\n\nmodel AccountDeletionTombstone {\n  id String @id @default(cuid())\n\n  userId         String\n  identifierType AuthIdentifierType\n  identifierHash String             @unique\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([identifierType])\n}\n\n//////////////////////////////////////////////////////\n// USER PROFILE\n//////////////////////////////////////////////////////\n\nmodel UserProfile {\n  id String @id @default(cuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  fullName String\n  email    String? @unique\n  gender   Gender?\n\n  profileImageUrl String?\n  dateOfBirth     DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([fullName])\n}\n\n//////////////////////////////////////////////////////\n// USER AUTH METHODS ⭐⭐⭐\n//////////////////////////////////////////////////////\n\nmodel UserAuth {\n  id String @id @default(cuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  provider       AuthProvider\n  identifierType AuthIdentifierType\n\n  /// phone OR email\n  identifier String\n\n  isVerified Boolean @default(false)\n  isPrimary  Boolean @default(false)\n\n  createdAt DateTime @default(now())\n\n  @@unique([provider, identifier])\n  @@index([identifier])\n}\n\n//////////////////////////////////////////////////////\n// GUEST / CHECKOUT IDENTITY\n//////////////////////////////////////////////////////\n\nmodel CustomerIdentity {\n  id String @id @default(cuid())\n\n  phone String?\n  email String?\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id])\n\n  isVerified Boolean   @default(false)\n  lastUsedAt DateTime?\n\n  addresses Address[]\n\n  createdAt DateTime @default(now())\n}\n\n//////////////////////////////////////////////////////\n// OTP\n//////////////////////////////////////////////////////\n\nmodel OTP {\n  id String @id @default(cuid())\n\n  identifier     String\n  identifierType AuthIdentifierType\n\n  codeHash String\n  type     OTPType\n\n  expiresAt DateTime\n  isUsed    Boolean  @default(false)\n\n  createdAt DateTime @default(now())\n\n  @@index([identifier])\n}\n\n//////////////////////////////////////////////////////\n// CITY\n//////////////////////////////////////////////////////\n\nmodel City {\n  id String @id @default(cuid())\n\n  name    String\n  state   String\n  country String @default(\"India\")\n\n  isActive Boolean @default(true)\n\n  branch    Branch?\n  addresses Address[]\n\n  createdAt DateTime @default(now())\n\n  @@unique([name, state])\n}\n\n//////////////////////////////////////////////////////\n// BRANCH (ONE PER CITY)\n//////////////////////////////////////////////////////\n\nmodel Branch {\n  id String @id @default(cuid())\n\n  name String\n\n  cityId String @unique\n  city   City   @relation(fields: [cityId], references: [id])\n\n  address String\n  pincode String\n\n  latitude  Float\n  longitude Float\n\n  serviceRadiusKm Float @default(12)\n\n  // Customer cancellation is allowed only if the request is made at least this many minutes before `scheduledAt`.\n  cancellationCutoffMinutes Int @default(60)\n\n  isActive         Boolean   @default(true)\n  deletedAt        DateTime?\n  scheduledPurgeAt DateTime?\n\n  admins          BranchAdmin[]\n  services        BranchService[]\n  bookingSettings BranchBookingSettings?\n  bookingClosures BranchBookingClosure[]\n\n  // Home base a professional registered under, for admin scoping/filtering only.\n  // Does NOT restrict which bookings a professional can be offered — that is\n  // radius-based via ProfessionalProfile.latitude/longitude/serviceRadiusKm.\n  professionals ProfessionalProfile[]\n\n  bookings Booking[]\n\n  carts Cart[]\n\n  coupons Coupon[]\n  offers  Offer[]\n\n  createdAt DateTime @default(now())\n\n  @@index([deletedAt])\n  @@index([scheduledPurgeAt])\n}\n\nmodel BranchBookingSettings {\n  id String @id @default(cuid())\n\n  branchId String @unique\n  branch   Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  timezone            String    @default(\"Asia/Kolkata\")\n  openingTime         String    @default(\"07:00\")\n  closingTime         String    @default(\"19:00\")\n  slotIntervalMinutes Int       @default(60)\n  minLeadMinutes      Int       @default(60)\n  maxAdvanceDays      Int       @default(30)\n  allowBookings       Boolean   @default(true)\n  weeklyOffDays       Weekday[]\n  closedMessage       String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel BranchBookingClosure {\n  id String @id @default(cuid())\n\n  branchId String\n  branch   Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  dateKey  String\n  reason   String?\n  isClosed Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([branchId, dateKey])\n  @@index([branchId, dateKey])\n}\n\n//////////////////////////////////////////////////////\n// BRANCH ADMINS\n//////////////////////////////////////////////////////\n\nmodel BranchAdmin {\n  id String @id @default(cuid())\n\n  userId   String\n  branchId String\n\n  isHead Boolean @default(false)\n\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  branch Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  assignedAt DateTime @default(now())\n\n  @@unique([userId, branchId])\n}\n\n//////////////////////////////////////////////////////\n// ADDRESS\n//////////////////////////////////////////////////////\n\nmodel Address {\n  id String @id @default(cuid())\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id])\n\n  identityId String?\n  identity   CustomerIdentity? @relation(fields: [identityId], references: [id])\n\n  label       AddressLabel @default(HOME)\n  customLabel String?\n\n  contactName  String?\n  contactPhone String?\n\n  addressLine1 String\n  addressLine2 String?\n\n  buildingName String?\n  floor        String?\n  doorNumber   String?\n\n  locality String?\n  landmark String?\n\n  cityId String?\n  city   City?   @relation(fields: [cityId], references: [id])\n\n  state   String?\n  country String  @default(\"India\")\n  pincode String?\n\n  latitude  Float\n  longitude Float\n\n  instructions String?\n\n  isPrimary Boolean @default(false)\n  isActive  Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  bookings Booking[]\n\n  @@index([cityId])\n  @@index([latitude, longitude])\n}\n\n//////////////////////////////////////////////////////\n// SERVICE TREE\n//////////////////////////////////////////////////////\n\nmodel ServiceNode {\n  id String @id @default(cuid())\n\n  parentId String?\n  parent   ServiceNode?  @relation(\"ServiceTree\", fields: [parentId], references: [id])\n  children ServiceNode[] @relation(\"ServiceTree\")\n\n  name String\n  slug String      @unique\n  type ServiceType\n\n  description String?\n\n  iconUrl  String?\n  coverUrl String?\n\n  gallery ServiceNodeMedia[]\n\n  isBookable  Boolean            @default(false)\n  bookingMode ServiceBookingMode @default(MULTI)\n\n  // Consultation-only services cannot be added to cart; users can only book a consultation/visit.\n  consultationOnly Boolean @default(false)\n\n  durationMinutes           Int?\n  durationType              ServiceDurationType @default(FIXED)\n  defaultPrice              Float?\n  priceType                 ServicePriceType?\n  pricingType               ServicePricingType  @default(FIXED)\n  cancellationCutoffMinutes Int?\n  bookingFields             Json?\n\n  variants     ServiceVariant[]\n  pricingRules PricingRule[]\n\n  sortOrder        Int       @default(0)\n  isActive         Boolean   @default(true)\n  deletedAt        DateTime?\n  scheduledPurgeAt DateTime?\n\n  branchServices       BranchService[]\n  professionalServices ProfessionalService[]\n\n  couponTargets CouponService[]\n  offerTargets  OfferService[]\n\n  bookingItems BookingItem[]\n  cartItems    CartItem[]\n  reviews      ServiceReview[]\n\n  faqs Faq[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([deletedAt])\n  @@index([scheduledPurgeAt])\n}\n\n//////////////////////////////////////////////////////\n// SERVICE FAQ\n//////////////////////////////////////////////////////\n\nmodel Faq {\n  id String @id @default(cuid())\n\n  question String\n  answer   String\n\n  serviceNodeId String?\n  serviceNode   ServiceNode? @relation(fields: [serviceNodeId], references: [id], onDelete: Cascade)\n\n  sortOrder Int     @default(0)\n  isActive  Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([serviceNodeId])\n  @@index([isActive])\n}\n\n//////////////////////////////////////////////////////\n// BRANCH SERVICE ENABLEMENT\n//////////////////////////////////////////////////////\n\nmodel BranchService {\n  id String @id @default(cuid())\n\n  branchId      String\n  serviceNodeId String\n\n  branch      Branch      @relation(fields: [branchId], references: [id])\n  serviceNode ServiceNode @relation(fields: [serviceNodeId], references: [id])\n\n  price Float?\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n\n  @@unique([branchId, serviceNodeId])\n}\n\n//////////////////////////////////////////////////////\n// BOOKINGS\n//////////////////////////////////////////////////////\n\nmodel Booking {\n  id        String  @id @default(cuid())\n  // Human-friendly booking reference (e.g. SW12345). Optional for older rows.\n  displayId String? @unique\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  branchId String\n  branch   Branch @relation(fields: [branchId], references: [id])\n\n  addressId String?\n  address   Address? @relation(fields: [addressId], references: [id], onDelete: SetNull)\n\n  couponId String?\n  coupon   Coupon? @relation(fields: [couponId], references: [id])\n\n  offerId String?\n  offer   Offer?  @relation(fields: [offerId], references: [id])\n\n  // Professional assignment lives on the booking (not per BookingItem): one\n  // professional performs the whole visit even when it covers multiple\n  // services. Nullable so every existing booking is unaffected.\n  assignedProfessionalId String?\n  assignedProfessional   ProfessionalProfile? @relation(\"BookingAssignedProfessional\", fields: [assignedProfessionalId], references: [id], onDelete: SetNull)\n  assignedAt             DateTime?\n\n  dispatchStatus   DispatchStatus @default(NOT_DISPATCHED)\n  dispatchedAt     DateTime?\n  dispatchAttempts Int            @default(0)\n\n  status           BookingStatus @default(BOOKED)\n  paymentStatus    PaymentStatus @default(PENDING)\n  isActive         Boolean       @default(true)\n  deletedAt        DateTime?\n  scheduledPurgeAt DateTime?\n\n  scheduledAt DateTime\n\n  subtotal    Float\n  taxAmount   Float? @default(0)\n  totalAmount Float\n\n  discountAmount Float? @default(0)\n\n  branchSnapshot  Json?\n  addressSnapshot Json?\n  cartSnapshot    Json?\n\n  notes String?\n\n  items                    BookingItem[]\n  timeline                 BookingTimeline[]\n  notificationDeliveryLogs NotificationDeliveryLog[]\n  paymentOrders            PaymentOrder[]\n  reviews                  ServiceReview[]\n  professionalOffers       BookingProfessionalOffer[]\n  professionalEarnings     ProfessionalEarning[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([branchId])\n  @@index([addressId])\n  @@index([couponId])\n  @@index([offerId])\n  @@index([status])\n  @@index([paymentStatus])\n  @@index([isActive])\n  @@index([deletedAt])\n  @@index([scheduledPurgeAt])\n  @@index([scheduledAt])\n  @@index([assignedProfessionalId])\n  @@index([dispatchStatus])\n}\n\nmodel PlatformSetting {\n  id String @id @default(cuid())\n\n  key String @unique @default(\"default\")\n\n  paymentEnabled                  Boolean        @default(false)\n  allowPayLater                   Boolean        @default(true)\n  activePaymentGateway            PaymentGateway @default(PHONEPE)\n  phonePeFeatureEnabled           Boolean        @default(true)\n  payuFeatureEnabled              Boolean        @default(true)\n  emailNotificationsEnabled       Boolean        @default(true)\n  welcomeEmailEnabled             Boolean        @default(true)\n  welcomeCouponsEnabled           Boolean        @default(true)\n  bookingConfirmationEmailEnabled Boolean        @default(true)\n  bookingCompletionEmailEnabled   Boolean        @default(true)\n  paymentConfirmationEmailEnabled Boolean        @default(true)\n  welcomeCouponCodes              String[]       @default([])\n  emailTemplates                  Json?\n\n  // Global platform commission applied to a professional's earning at the\n  // moment a booking's earning is created. Admin-configurable so it never\n  // needs a code change/redeploy to adjust. Changing this value only\n  // affects earnings created afterwards — it is never applied\n  // retroactively, since each ProfessionalEarning stores its own computed\n  // amounts, not a rate.\n  platformCommissionPercent Float @default(20)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel NotificationDeliveryLog {\n  id String @id @default(cuid())\n\n  channel NotificationDeliveryChannel\n  event   NotificationEvent\n  status  NotificationDeliveryStatus\n\n  recipient    String?\n  subject      String?\n  provider     String?\n  errorMessage String?\n  payload      Json?\n\n  userId String?\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  bookingId String?\n  booking   Booking? @relation(fields: [bookingId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  @@index([channel, event, createdAt])\n  @@index([status, createdAt])\n  @@index([userId])\n  @@index([bookingId])\n}\n\nmodel PaymentOrder {\n  id String @id @default(cuid())\n\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  gateway         PaymentGateway\n  providerOrderId String?        @unique\n  merchantOrderId String         @unique\n\n  state  String\n  amount Int\n\n  rawRequest  Json?\n  rawResponse Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([bookingId])\n  @@index([merchantOrderId])\n  @@index([gateway])\n}\n\nmodel Coupon {\n  id String @id @default(cuid())\n\n  code        String  @unique\n  title       String?\n  description String?\n\n  badge    String?\n  meta     String?\n  imageUrl String?\n\n  isPublic         Boolean @default(true)\n  autoApply        Boolean @default(false)\n  firstBookingOnly Boolean @default(false)\n  minServiceCount  Int?\n\n  branchId String?\n  branch   Branch? @relation(fields: [branchId], references: [id])\n\n  discountType CouponDiscountType\n  value        Float\n\n  maxDiscountAmount Float?\n  minOrderAmount    Float? @default(0)\n\n  isActive  Boolean   @default(true)\n  startsAt  DateTime?\n  expiresAt DateTime?\n\n  bookings       Booking[]\n  serviceTargets CouponService[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([code])\n  @@index([branchId])\n  @@index([isPublic])\n  @@index([autoApply])\n}\n\nmodel Offer {\n  id String @id @default(cuid())\n\n  title       String\n  description String?\n\n  badge    String?\n  meta     String?\n  imageUrl String?\n\n  branchId String?\n  branch   Branch? @relation(fields: [branchId], references: [id])\n\n  discountType OfferDiscountType\n  value        Float\n\n  maxDiscountAmount Float?\n  minOrderAmount    Float? @default(0)\n\n  isPublic         Boolean @default(true)\n  autoApply        Boolean @default(false)\n  firstBookingOnly Boolean @default(false)\n  minServiceCount  Int?\n\n  isActive  Boolean   @default(true)\n  startsAt  DateTime?\n  expiresAt DateTime?\n\n  serviceTargets OfferService[]\n  bookings       Booking[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([branchId])\n  @@index([isPublic])\n  @@index([autoApply])\n  @@index([isActive])\n}\n\nmodel OfferService {\n  id String @id @default(cuid())\n\n  offerId       String\n  serviceNodeId String\n\n  offer       Offer       @relation(fields: [offerId], references: [id], onDelete: Cascade)\n  serviceNode ServiceNode @relation(fields: [serviceNodeId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([offerId, serviceNodeId])\n  @@index([offerId])\n  @@index([serviceNodeId])\n}\n\nmodel CouponService {\n  id String @id @default(cuid())\n\n  couponId      String\n  serviceNodeId String\n\n  coupon      Coupon      @relation(fields: [couponId], references: [id], onDelete: Cascade)\n  serviceNode ServiceNode @relation(fields: [serviceNodeId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@unique([couponId, serviceNodeId])\n  @@index([couponId])\n  @@index([serviceNodeId])\n}\n\n//////////////////////////////////////////////////////\n// HOMEPAGE BANNERS (CMS)\n//////////////////////////////////////////////////////\n\nenum BannerSize {\n  HERO\n  GRID\n  SPOTLIGHT\n}\n\nmodel Banner {\n  id String @id @default(cuid())\n\n  size BannerSize @default(HERO)\n\n  title    String?\n  subtitle String?\n  ctaLabel String?\n  linkUrl  String?\n  imageUrl String\n\n  sortOrder Int     @default(0)\n  isActive  Boolean @default(true)\n\n  startsAt  DateTime?\n  expiresAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isActive])\n  @@index([sortOrder])\n  @@index([size])\n}\n\n//////////////////////////////////////////////////////\n// HOMEPAGE TESTIMONIALS (CMS)\n//////////////////////////////////////////////////////\n\nmodel Testimonial {\n  id String @id @default(cuid())\n\n  customerName String\n  customerRole String?\n  avatarUrl    String?\n  quote        String\n  rating       Int?\n\n  sortOrder Int     @default(0)\n  isActive  Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isActive])\n  @@index([sortOrder])\n}\n\nmodel BookingItem {\n  id String @id @default(cuid())\n\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  serviceNodeId String?\n  serviceNode   ServiceNode? @relation(fields: [serviceNodeId], references: [id], onDelete: SetNull)\n\n  variantId String?\n  variant   ServiceVariant? @relation(fields: [variantId], references: [id], onDelete: SetNull)\n\n  quantity        Float  @default(1)\n  pricingQuantity Float?\n  duration        Float?\n  price           Float\n  lineTotal       Float?\n  inputData       Json?\n  serviceSnapshot Json?\n\n  review ServiceReview?\n\n  createdAt DateTime @default(now())\n\n  @@index([bookingId])\n  @@index([serviceNodeId])\n  @@index([variantId])\n}\n\nmodel ServiceVariant {\n  id String @id @default(cuid())\n\n  serviceId String\n  service   ServiceNode @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  name      String\n  price     Float\n  sortOrder Int    @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  bookingItems BookingItem[]\n\n  @@unique([serviceId, name])\n  @@index([serviceId])\n}\n\nmodel PricingRule {\n  id String @id @default(cuid())\n\n  serviceId String\n  service   ServiceNode @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  type      PricingRuleType\n  baseRate  Float\n  sortOrder Int             @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([serviceId])\n}\n\nmodel ServiceReview {\n  id String @id @default(cuid())\n\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  bookingItemId String      @unique\n  bookingItem   BookingItem @relation(fields: [bookingItemId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  serviceNodeId String\n  serviceNode   ServiceNode @relation(fields: [serviceNodeId], references: [id], onDelete: Cascade)\n\n  // Snapshot of who actually performed the work, captured when the review is\n  // created. Kept alongside (not instead of) Booking.assignedProfessionalId\n  // so a review stays correct even if assignment data changes later.\n  professionalId String?\n  professional   ProfessionalProfile? @relation(\"ServiceReviewProfessional\", fields: [professionalId], references: [id], onDelete: SetNull)\n\n  rating  Int\n  comment String?\n\n  isVisible Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([bookingId])\n  @@index([userId, createdAt(sort: Desc)])\n  @@index([serviceNodeId, createdAt(sort: Desc)])\n  @@index([professionalId, createdAt(sort: Desc)])\n}\n\nmodel BookingTimeline {\n  id String @id @default(cuid())\n\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  status        BookingStatus?\n  paymentStatus PaymentStatus?\n\n  message String?\n\n  createdById String?\n  createdBy   User?   @relation(fields: [createdById], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@index([bookingId])\n}\n\nmodel Notification {\n  id String @id @default(cuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  campaignId String?\n  campaign   NotificationCampaign? @relation(fields: [campaignId], references: [id], onDelete: SetNull)\n\n  type     NotificationType\n  title    String\n  message  String?\n  linkUrl  String?\n  imageUrl String?\n  data     Json?\n\n  deliveryStatus NotificationDeliveryState @default(PENDING)\n  deliveredAt    DateTime?\n  isRead         Boolean                   @default(false)\n  readAt         DateTime?\n  openedAt       DateTime?\n  clickedAt      DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([userId, isRead, createdAt(sort: Desc)])\n  @@index([campaignId, createdAt(sort: Desc)])\n  @@index([deliveryStatus, createdAt(sort: Desc)])\n}\n\nmodel NotificationCampaign {\n  id String @id @default(cuid())\n\n  title   String\n  message String\n  type    NotificationType\n\n  audienceType    NotificationAudienceType\n  audienceSegment NotificationAudienceSegment?\n  targetUserIds   String[]                     @default([])\n\n  status NotificationCampaignStatus @default(DRAFT)\n\n  deepLinkPath String?\n  imageUrl     String?\n  data         Json?\n\n  scheduledAt         DateTime?\n  processingStartedAt DateTime?\n  sentAt              DateTime?\n\n  resolvedAudienceCount Int @default(0)\n  deliveredCount        Int @default(0)\n  failedCount           Int @default(0)\n  skippedCount          Int @default(0)\n  openedCount           Int @default(0)\n  clickedCount          Int @default(0)\n\n  lastError String?\n\n  createdById String\n  createdBy   User   @relation(\"NotificationCampaignCreatedBy\", fields: [createdById], references: [id], onDelete: Cascade)\n\n  notifications Notification[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, scheduledAt])\n  @@index([createdById, createdAt(sort: Desc)])\n}\n\n//////////////////////////////////////////////////////\n// DEVICE TOKENS (FCM push notifications)\n//////////////////////////////////////////////////////\n\nmodel DeviceToken {\n  id String @id @default(cuid())\n\n  token      String  @unique\n  platform   String\n  deviceId   String?\n  appVersion String?\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\n//////////////////////////////////////////////////////\n// CART\n//////////////////////////////////////////////////////\n\nmodel Cart {\n  id String @id @default(cuid())\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  branchId String\n  branch   Branch @relation(fields: [branchId], references: [id])\n\n  items CartItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, branchId])\n  @@index([userId])\n  @@index([branchId])\n}\n\nmodel CartItem {\n  id String @id @default(cuid())\n\n  cartId String\n  cart   Cart   @relation(fields: [cartId], references: [id], onDelete: Cascade)\n\n  serviceNodeId String\n  serviceNode   ServiceNode @relation(fields: [serviceNodeId], references: [id])\n\n  quantity Int   @default(1)\n  price    Float\n\n  createdAt DateTime @default(now())\n\n  @@index([cartId])\n  @@index([serviceNodeId])\n}\n\n//////////////////////////////////////////////////////\n// EMAIL VERIFICATION TOKEN\n//////////////////////////////////////////////////////\n\nmodel EmailVerificationToken {\n  id String @id @default(cuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  tokenHash String   @unique\n  expiresAt DateTime\n\n  createdAt DateTime @default(now())\n\n  @@index([tokenHash])\n}\n\n//////////////////////////////////////////////////////\n// MEDIA\n//////////////////////////////////////////////////////\n\n//////////////////////////////////////////////////////\n// MEDIA FOLDER (NESTED)\n//////////////////////////////////////////////////////\n\nmodel MediaFolder {\n  id   String @id @default(cuid())\n  name String\n  slug String\n\n  parentId String?\n\n  parent MediaFolder? @relation(\"FolderHierarchy\", fields: [parentId], references: [id], onDelete: SetNull)\n\n  children MediaFolder[] @relation(\"FolderHierarchy\")\n\n  media Media[]\n\n  createdAt DateTime @default(now())\n}\n\nmodel Media {\n  id String @id @default(cuid())\n\n  url      String\n  key      String @unique\n  fileName String\n\n  folderId String?\n  folder   MediaFolder? @relation(fields: [folderId], references: [id], onDelete: SetNull)\n\n  mimeType String?\n  size     Int?\n\n  width  Int?\n  height Int?\n\n  createdAt             DateTime               @default(now())\n  serviceGallery        ServiceNodeMedia[]\n  professionalDocuments ProfessionalDocument[]\n}\n\n//////////////////////////////////////////////////////\n// SERVICE NODE MEDIA\n//////////////////////////////////////////////////////\n\nmodel ServiceNodeMedia {\n  id String @id @default(cuid())\n\n  serviceNodeId String\n  mediaId       String\n\n  serviceNode ServiceNode @relation(fields: [serviceNodeId], references: [id], onDelete: Cascade)\n  media       Media       @relation(fields: [mediaId], references: [id], onDelete: Cascade)\n\n  sortOrder Int @default(0)\n\n  createdAt DateTime @default(now())\n\n  @@unique([serviceNodeId, mediaId])\n  @@index([serviceNodeId])\n  @@index([mediaId])\n}\n\n//////////////////////////////////////////////////////\n// PROFESSIONAL / PARTNER MARKETPLACE (DOMAIN FOUNDATION)\n//////////////////////////////////////////////////////\n//\n// User remains the account/authentication entity. All professional-specific\n// data lives here, one layer out, the same way UserProfile extends User.\n// Professionals reference the EXISTING service catalogue (ServiceNode) and\n// the EXISTING Booking — no parallel catalogue or parallel booking model.\n//////////////////////////////////////////////////////\n\nmodel ProfessionalProfile {\n  id String @id @default(cuid())\n\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  displayName     String\n  bio             String?\n  profileImageUrl String?\n  experienceYears Int?\n\n  //////////////////////////////////////////////////\n  // VERIFICATION (admin-controlled, separate from availability)\n  //////////////////////////////////////////////////\n  verificationStatus ProfessionalVerificationStatus @default(PENDING)\n  verificationNote   String?\n  verifiedAt         DateTime?\n  verifiedById       String?\n  verifiedBy         User?                          @relation(\"ProfessionalVerifiedBy\", fields: [verifiedById], references: [id], onDelete: SetNull)\n\n  //////////////////////////////////////////////////\n  // AVAILABILITY (professional/app-controlled, separate from verification)\n  //////////////////////////////////////////////////\n  availabilityStatus    ProfessionalAvailabilityStatus @default(OFFLINE)\n  availabilityUpdatedAt DateTime?\n\n  //////////////////////////////////////////////////\n  // LOCATION\n  // Plain Float columns today so this can be backed by a PostGIS geography\n  // column or mirrored into Redis GEO later without a model redesign.\n  //////////////////////////////////////////////////\n  latitude          Float?\n  longitude         Float?\n  locationUpdatedAt DateTime?\n  serviceRadiusKm   Float     @default(10)\n\n  // Home base for admin scoping/filtering ONLY. Does not restrict which\n  // bookings this professional can be offered — matching is radius-based.\n  branchId String?\n  branch   Branch? @relation(fields: [branchId], references: [id], onDelete: SetNull)\n\n  //////////////////////////////////////////////////\n  // JOB STATISTICS (denormalized counters; no calculation logic here)\n  //////////////////////////////////////////////////\n  totalJobsCompleted Int    @default(0)\n  totalJobsCancelled Int    @default(0)\n  averageRating      Float?\n  ratingCount        Int    @default(0)\n\n  isActive         Boolean   @default(true)\n  deletedAt        DateTime?\n  scheduledPurgeAt DateTime?\n\n  services         ProfessionalService[]\n  documents        ProfessionalDocument[]\n  offers           BookingProfessionalOffer[]\n  assignedBookings Booking[]                  @relation(\"BookingAssignedProfessional\")\n  reviews          ServiceReview[]            @relation(\"ServiceReviewProfessional\")\n  earnings         ProfessionalEarning[]\n  bankAccounts     ProfessionalBankAccount[]\n  payouts          Payout[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([verificationStatus])\n  @@index([availabilityStatus])\n  @@index([verificationStatus, availabilityStatus])\n  @@index([latitude, longitude])\n  @@index([branchId])\n  @@index([isActive])\n  @@index([deletedAt])\n  @@index([scheduledPurgeAt])\n}\n\n//////////////////////////////////////////////////////\n// PROFESSIONAL <-> EXISTING SERVICE CATALOGUE\n//////////////////////////////////////////////////////\n\nmodel ProfessionalService {\n  id String @id @default(cuid())\n\n  professionalId String\n  professional   ProfessionalProfile @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  serviceNodeId String\n  serviceNode   ServiceNode @relation(fields: [serviceNodeId], references: [id], onDelete: Cascade)\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([professionalId, serviceNodeId])\n  @@index([professionalId])\n  @@index([serviceNodeId])\n}\n\n//////////////////////////////////////////////////////\n// PROFESSIONAL VERIFICATION DOCUMENTS\n//////////////////////////////////////////////////////\n\nmodel ProfessionalDocument {\n  id String @id @default(cuid())\n\n  professionalId String\n  professional   ProfessionalProfile @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  type   ProfessionalDocumentType\n  status ProfessionalDocumentStatus @default(PENDING)\n\n  mediaId String?\n  media   Media?  @relation(fields: [mediaId], references: [id], onDelete: SetNull)\n\n  documentNumber String?\n  note           String?\n\n  reviewedById String?\n  reviewedBy   User?     @relation(\"ProfessionalDocumentReviewedBy\", fields: [reviewedById], references: [id], onDelete: SetNull)\n  reviewedAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([professionalId])\n  @@index([type])\n  @@index([status])\n}\n\n//////////////////////////////////////////////////////\n// BOOKING <-> PROFESSIONAL JOB OFFERS\n//////////////////////////////////////////////////////\n// One row per candidate professional per booking. A booking may fan out to\n// many offers; the unique constraint below prevents duplicate offers to the\n// same professional for the same booking. No auto-expiry/matching logic is\n// implemented here — this is the data foundation only.\n//////////////////////////////////////////////////////\n\nmodel BookingProfessionalOffer {\n  id String @id @default(cuid())\n\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  professionalId String\n  professional   ProfessionalProfile @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  status BookingProfessionalOfferStatus @default(PENDING)\n\n  // Which dispatch round this offer belongs to (1 = first batch sent).\n  // Not used for logic — batches are re-derived by excluding professionals\n  // who already have a row for this booking — but useful for observability.\n  batchNumber Int @default(1)\n\n  distanceKm Float?\n\n  sentAt      DateTime?\n  viewedAt    DateTime?\n  respondedAt DateTime?\n  expiresAt   DateTime?\n\n  responseNote String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([bookingId, professionalId])\n  @@index([bookingId])\n  @@index([professionalId])\n  @@index([status])\n  @@index([bookingId, status])\n  @@index([professionalId, status])\n  @@index([expiresAt])\n  @@index([status, expiresAt])\n}\n\n//////////////////////////////////////////////////////\n// PROFESSIONAL EARNINGS (LEDGER FOUNDATION)\n//////////////////////////////////////////////////////\n// One row per (professional, booking). Amounts are actual computed values,\n// never a stored commission rate — calculation logic is out of scope for\n// this phase.\n//////////////////////////////////////////////////////\n\nmodel ProfessionalEarning {\n  id String @id @default(cuid())\n\n  professionalId String\n  professional   ProfessionalProfile @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  grossAmount       Float\n  platformFeeAmount Float @default(0)\n  netAmount         Float\n\n  status ProfessionalEarningStatus @default(PENDING)\n\n  payoutId String?\n  payout   Payout? @relation(fields: [payoutId], references: [id], onDelete: SetNull)\n\n  notes String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([professionalId, bookingId])\n  @@index([professionalId])\n  @@index([bookingId])\n  @@index([status])\n  @@index([professionalId, status])\n  @@index([payoutId])\n}\n\n//////////////////////////////////////////////////////\n// PROFESSIONAL BANK ACCOUNTS\n//////////////////////////////////////////////////////\n// NOTE: accountNumber is stored as plain text at the schema level, matching\n// no existing precedent in this codebase for encrypted-at-rest fields.\n// Application code must mask this value in every API response and should\n// encrypt it at rest before this table holds real professional data.\n//////////////////////////////////////////////////////\n\nmodel ProfessionalBankAccount {\n  id String @id @default(cuid())\n\n  professionalId String\n  professional   ProfessionalProfile @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  accountHolderName String\n  accountNumber     String\n  ifscCode          String\n  bankName          String?\n  upiId             String?\n\n  isPrimary  Boolean   @default(false)\n  isVerified Boolean   @default(false)\n  verifiedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  payouts Payout[]\n\n  @@index([professionalId])\n  @@index([professionalId, isPrimary])\n}\n\n//////////////////////////////////////////////////////\n// PAYOUTS\n//////////////////////////////////////////////////////\n// Batches one or more ProfessionalEarning rows into a single payment run.\n// Automated processing is out of scope for this phase.\n//////////////////////////////////////////////////////\n\nmodel Payout {\n  id String @id @default(cuid())\n\n  professionalId String\n  professional   ProfessionalProfile @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n\n  bankAccountId String?\n  bankAccount   ProfessionalBankAccount? @relation(fields: [bankAccountId], references: [id], onDelete: SetNull)\n\n  amount Float\n\n  status PayoutStatus @default(PENDING)\n\n  earnings ProfessionalEarning[]\n\n  reference     String?\n  failureReason String?\n  processedAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([professionalId])\n  @@index([status])\n  @@index([bankAccountId])\n}\n"
}

